insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$sao-jose-dos-ausentes$q$, $q$https://www.saojosedosausentes.rs.gov.br/publicacaolegal/decreto-no-11-de-24-de-fevereiro-de-2021-proibe-trafego-de-caminhoes-acima-de-10dez-toneladas-e-pbt-de-18dezoitotoneladas-em-toda-a-extensao-da-avenida-ismenia-batista-ribeiro-velho/ (Decreto 11/2021)$q$, $q$Ato oficial do Município de São José dos Ausentes: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria derivada do OpenStreetMap: ODbL 1.0 (© colaboradores do OpenStreetMap), base derivada separada do OSM.$q$, 6, $q$Uma regra ativa (confiança média): Decreto 11/2021 proíbe o tráfego de caminhões em toda a extensão da Av. Ismênia Batista Ribeiro Velho, 24 h. A redação ('acima de 10 toneladas e PBT 18 toneladas') é ambígua entre carga útil (10 t) e PBT (18 t): modelado PBT acima de 18 t, o piso seguro (proibido em qualquer leitura). PDF escaneado, lido na imagem da página. Sem ato posterior na busca do site da Prefeitura. Jurisdição tratada como municipal (via urbana sem ref de rodovia no OSM; a BR-285 é outra via, ~1,2 km a leste), mas houve ação do DNIT na avenida em 2023.$q$);
